<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { ArrowDown, ArrowUp, Check, Eye, FileUp, ImagePlus, Save, Send, Trash2 } from 'lucide-vue-next'
import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router'
import { ApiError, createAppeal, createDraft, fetchDraft, fetchDraftAudits, listDrafts, submitDraft, updateDraft, uploadMedia } from '../api/client'
import type { Draft, DraftMedia, PostAudit, PostStatus, SaveDraftRequest } from '../api/types'
import { renderSafeMarkdown } from '../utils/markdown'

const route = useRoute(); const router = useRouter(); const draftId = computed(() => route.params.draftId ? Number(route.params.draftId) : undefined)
const draftList = ref<Draft[]>([]); const audits = ref<PostAudit[]>([]); const saving = ref(false); const submitting = ref(false); const uploading = ref(false); const dirty = ref(false); const conflict = ref(false); const feedback = ref(''); const error = ref(''); const currentStatus = ref<PostStatus>('DRAFT'); const reviewReason = ref(''); const appealReason = ref('')
const form = reactive<SaveDraftRequest>({ title: '', content: '', tags: [], type: 'TEXT', mediaIds: [], media: [], theme: 'DEDUCTION', contentKind: 'CASE_FILE', difficulty: 'MEDIUM', solvable: true, clues: '', suspects: '', timeline: '', question: '', answerKeywords: '', solution: '' })
const tagText = computed({ get: () => form.tags.join(', '), set: value => { form.tags = value.split(',').map(tag => tag.trim()).filter(Boolean).slice(0, 12) } })
const preview = computed(() => renderSafeMarkdown(form.content || '*开始写下你的观测记录…*', form.media)); const wordCount = computed(() => form.content.trim().length)
let saveTimer: number | undefined; let hydrating = false; let editRevision = 0; let skipNextRouteLoad = false; let activeSave: Promise<boolean> | null = null

function fill(value: Draft) { window.clearTimeout(saveTimer); hydrating = true; const media = value.media?.length ? value.media.map(item => ({ ...item })) : value.mediaIds.map((mediaId, sortOrder) => ({ mediaId, role: 'INLINE' as const, altText: '', sortOrder })); Object.assign(form, { title: value.title, content: value.content, tags: [...value.tags], type: value.type, mediaIds: media.map(item => item.mediaId), media, theme: value.theme, contentKind: value.contentKind, difficulty: value.difficulty, solvable: value.solvable, clues: value.clues, suspects: value.suspects, timeline: value.timeline, question: value.question, answerKeywords: value.answerKeywords, solution: value.solution, version: value.version }); currentStatus.value = value.status; reviewReason.value = value.reviewReason ?? ''; dirty.value = false; conflict.value = false; hydrating = false }
async function load() { try { draftList.value = await listDrafts(); if (draftId.value) { fill(await fetchDraft(draftId.value)); audits.value = await fetchDraftAudits(draftId.value) } } catch (reason) { error.value = reason instanceof Error ? reason.message : '草稿暂时不可用' } }
function armSaveTimer() { window.clearTimeout(saveTimer); saveTimer = window.setTimeout(() => void save(), 5000) }
function scheduleSave() { if (hydrating) return; dirty.value = true; editRevision += 1; armSaveTimer() }
async function persistDraft() { if (!form.title.trim() && !form.content.trim()) { error.value = '请先填写标题或正文'; return false } const media = (form.media ?? []).map((item, sortOrder) => ({ mediaId: item.mediaId, role: item.role, altText: item.altText.trim(), sortOrder })); if (media.some(item => !item.altText)) { error.value = '请为每个媒体填写替代文本'; return false } const payload = { ...form, media, mediaIds: media.map(item => item.mediaId) }; const revision = editRevision; saving.value = true; error.value = ''; try { const result = draftId.value ? await updateDraft(draftId.value, payload) : await createDraft(payload); if (revision === editRevision) fill(result); else { hydrating = true; form.version = result.version; hydrating = false } conflict.value = false; feedback.value = `已保存 ${new Date().toLocaleTimeString()}`; if (!draftId.value) { skipNextRouteLoad = true; await router.replace(`/write/${result.id}`) } return true } catch (reason) { conflict.value = reason instanceof ApiError && reason.code === 'VERSION_CONFLICT'; error.value = conflict.value ? '草稿已在其他位置更新。当前编辑内容仍保留，请选择加载服务端版本或复制后手动合并。' : reason instanceof Error ? reason.message : '保存失败，请重试'; return false } finally { saving.value = false; if (dirty.value && revision !== editRevision) armSaveTimer() } }
async function save() { if (activeSave) return activeSave; if (draftId.value && !dirty.value) return true; activeSave = persistDraft(); try { return await activeSave } finally { activeSave = null } }
async function ensureLatestSaved() { for (let attempt = 0; attempt < 3; attempt += 1) { if (!await save()) return false; if (!dirty.value) return true } error.value = '编辑仍在快速变化，请稍停片刻后重新提交。'; return false }
async function submit() { if (!await ensureLatestSaved() || !draftId.value) return; submitting.value = true; error.value = ''; try { const result = await submitDraft(draftId.value, form.version ?? 0); fill(result); audits.value = await fetchDraftAudits(draftId.value); feedback.value = '已提交审核，审核结果会在通知中告知。' } catch (reason) { conflict.value = reason instanceof ApiError && reason.code === 'VERSION_CONFLICT'; error.value = conflict.value ? '投稿前草稿版本发生变化，请加载服务端版本并确认内容后重新提交。' : reason instanceof Error ? reason.message : '提交失败' } finally { submitting.value = false } }
async function reloadServerDraft() { if (!draftId.value || !window.confirm('加载服务端版本会替换当前未保存内容，确定继续吗？')) return; error.value = ''; try { fill(await fetchDraft(draftId.value)); feedback.value = '已加载服务端最新版本' } catch (reason) { error.value = reason instanceof Error ? reason.message : '服务端版本暂时无法加载' } }
async function upload(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; uploading.value = true; error.value = ''; try { const uploaded = await uploadMedia(file); const items = [...(form.media ?? [])]; const role: DraftMedia['role'] = file.type.startsWith('image/') && !items.some(item => item.role === 'COVER') ? 'COVER' : 'INLINE'; items.push({ mediaId: uploaded.mediaId, role, altText: file.name.replace(/\.[^.]+$/, '').replace(/[-_]+/g, ' '), sortOrder: items.length, contentType: uploaded.contentType }); form.media = items; form.mediaIds = items.map(item => item.mediaId); scheduleSave(); feedback.value = '媒体已上传，补充替代文本后会随草稿保存' } catch (reason) { error.value = reason instanceof Error ? reason.message : '媒体上传失败，请重试' } finally { uploading.value = false; (event.target as HTMLInputElement).value = '' } }
function removeMedia(index: number) { const items = (form.media ?? []).filter((_, current) => current !== index).map((item, sortOrder) => ({ ...item, sortOrder })); form.media = items; form.mediaIds = items.map(item => item.mediaId); scheduleSave() }
function moveMedia(index: number, direction: -1 | 1) { const items = [...(form.media ?? [])]; const next = index + direction; if (next < 0 || next >= items.length) return; [items[index], items[next]] = [items[next], items[index]]; form.media = items.map((item, sortOrder) => ({ ...item, sortOrder })); form.mediaIds = form.media.map(item => item.mediaId); scheduleSave() }
function setMediaRole(index: number, role: DraftMedia['role']) { const items = [...(form.media ?? [])]; if (role === 'COVER') items.forEach((item, current) => { if (current !== index && item.role === 'COVER') items[current] = { ...item, role: 'INLINE' } }); items[index] = { ...items[index], role }; form.media = items; scheduleSave() }
function changeMediaRole(index: number, event: Event) { setMediaRole(index, (event.target as HTMLSelectElement).value as DraftMedia['role']) }
async function insertMedia(index: number) { const item = form.media?.[index]; if (!item) return; const altText = item.altText.trim(); if (!altText) { error.value = '请先填写媒体替代文本'; return } const reference = new RegExp(`media://${item.mediaId}(?![0-9])`); if (reference.test(form.content)) { feedback.value = `媒体 #${item.mediaId} 已在正文中`; return } setMediaRole(index, 'INLINE'); const textarea = document.querySelector<HTMLTextAreaElement>('#draft-content'); const start = textarea?.selectionStart ?? form.content.length; const end = textarea?.selectionEnd ?? start; const escapedAlt = altText.replace(/([\\\]])/g, '\\$1'); const syntax = `![${escapedAlt}](media://${item.mediaId})`; const before = form.content.slice(0, start); const after = form.content.slice(end); const prefix = before && !before.endsWith('\n') ? '\n\n' : ''; const suffix = after && !after.startsWith('\n') ? '\n\n' : ''; form.content = `${before}${prefix}${syntax}${suffix}${after}`; error.value = ''; feedback.value = `媒体 #${item.mediaId} 已插入正文`; await nextTick(); const cursor = start + prefix.length + syntax.length; textarea?.focus(); textarea?.setSelectionRange(cursor, cursor) }
async function appeal() { if (!draftId.value || !appealReason.value.trim()) return; try { await createAppeal(draftId.value, appealReason.value.trim()); appealReason.value = ''; feedback.value = '申诉已提交，运营团队会重新查看。' } catch (reason) { error.value = reason instanceof Error ? reason.message : '申诉提交失败' } }
function beforeLeave(event: BeforeUnloadEvent) { if (dirty.value) { event.preventDefault(); event.returnValue = '' } }
watch(form, scheduleSave, { deep: true, flush: 'sync' }); watch(draftId, () => { if (skipNextRouteLoad) { skipNextRouteLoad = false; return } void load() }); onMounted(load); onMounted(() => window.addEventListener('beforeunload', beforeLeave)); onBeforeUnmount(() => { window.clearTimeout(saveTimer); window.removeEventListener('beforeunload', beforeLeave) }); onBeforeRouteLeave(() => !dirty.value || window.confirm('草稿还有未保存的更改，确定离开吗？'))
</script>

<template>
  <div class="page-stack write-page"><section class="page-intro"><span class="eyebrow">CREATOR'S DESK</span><h1>把你的观测记录放上来。</h1><p>先保存草稿，再决定何时让审核员看到它。</p></section>
    <div class="write-layout"><form class="editor-panel" @submit.prevent="submit"><div class="editor-toolbar"><span>{{ saving ? '保存中…' : feedback || '自动保存已开启（5 秒防抖）' }}</span><span>{{ wordCount }} 字 · v{{ form.version ?? 0 }}</span></div>
      <label for="draft-title">标题</label><input id="draft-title" v-model="form.title" required maxlength="160" placeholder="给这宗案件一个可被记住的名字" />
      <div class="field-grid"><label>主题<select v-model="form.theme"><option value="DEDUCTION">推理馆</option><option value="SCI_FI">科幻馆</option><option value="COSMOS">宇宙档案</option></select></label><label>内容类型<select v-model="form.contentKind"><option value="CASE_FILE">案件档案</option><option value="PUZZLE">解谜题</option><option value="FICTION">短篇小说</option><option value="WORLDBUILDING">世界观</option><option value="COSMIC_ARTICLE">宇宙文章</option></select></label><label>难度<select v-model="form.difficulty"><option value="EASY">简单</option><option value="MEDIUM">中等</option><option value="HARD">困难</option></select></label></div>
      <label for="draft-tags">标签</label><input id="draft-tags" v-model="tagText" placeholder="时间线, 证词, 观测记录" />
      <label for="draft-content">正文 Markdown</label><textarea id="draft-content" v-model="form.content" required rows="16" placeholder="从现场开始。支持 Markdown…" />
      <div class="field-grid"><label>线索<textarea v-model="form.clues" rows="4" placeholder="每行一条" /></label><label>嫌疑人<textarea v-model="form.suspects" rows="4" /></label><label>时间线<textarea v-model="form.timeline" rows="4" /></label></div>
      <label for="draft-question">问题</label><input id="draft-question" v-model="form.question" placeholder="希望读者回答什么？" /><label for="draft-keywords">答案关键词</label><input id="draft-keywords" v-model="form.answerKeywords" placeholder="用逗号分隔多个可接受答案" /><label for="draft-solution">解析</label><textarea id="draft-solution" v-model="form.solution" rows="4" />
      <label for="cover-upload" class="upload-field"><FileUp :size="16" /> {{ uploading ? '上传中…' : '上传封面或媒体' }}<input id="cover-upload" type="file" accept="image/png,image/jpeg,image/webp,video/mp4" @change="upload" /></label>
      <div v-if="form.media?.length" class="media-queue"><div v-for="(item, index) in form.media" :key="item.mediaId" class="media-queue-row"><span>媒体 #{{ item.mediaId }}</span><label class="sr-only" :for="`media-role-${item.mediaId}`">媒体 #{{ item.mediaId }} 角色</label><select :id="`media-role-${item.mediaId}`" :value="item.role" @change="changeMediaRole(index, $event)"><option value="COVER">封面</option><option value="INLINE">正文媒体</option></select><label class="sr-only" :for="`media-alt-${item.mediaId}`">媒体 #{{ item.mediaId }} 替代文本</label><input :id="`media-alt-${item.mediaId}`" v-model="item.altText" maxlength="240" placeholder="描述画面内容" /><small>{{ item.contentType?.startsWith('video/') ? '视频' : '图片' }} · 等待审核</small><button type="button" :aria-label="`插入正文媒体 #${item.mediaId}`" @click="insertMedia(index)"><ImagePlus :size="14" /></button><button type="button" :aria-label="`上移媒体 #${item.mediaId}`" @click="moveMedia(index, -1)"><ArrowUp :size="14" /></button><button type="button" :aria-label="`下移媒体 #${item.mediaId}`" @click="moveMedia(index, 1)"><ArrowDown :size="14" /></button><button type="button" :aria-label="`删除媒体 #${item.mediaId}`" @click="removeMedia(index)"><Trash2 :size="14" /></button></div></div>
      <p v-if="error" class="form-error" role="alert">{{ error }}</p><div v-if="conflict" class="conflict-actions"><button class="button button-quiet" type="button" @click="reloadServerDraft">加载服务端版本</button><span>当前输入不会自动覆盖服务端内容。</span></div><div class="editor-actions"><button class="button button-quiet" type="button" :disabled="saving" @click="save"><Save :size="15" /> 保存草稿</button><button class="button button-primary" type="submit" :disabled="submitting || uploading || conflict"><Send :size="15" /> {{ submitting ? '提交中…' : '提交审核' }}</button></div>
    </form>
    <aside class="preview-panel"><div class="editor-toolbar"><span><Eye :size="15" /> 实时预览</span></div><article class="markdown-preview" v-html="preview" /><div class="audit-timeline" aria-label="审核进度"><span class="complete"><Check :size="14" /> 草稿</span><span :class="{ complete: currentStatus !== 'DRAFT' }"><Check :size="14" /> 已投稿</span><span v-if="currentStatus === 'PENDING'" class="current">等待审核</span><span v-else-if="currentStatus === 'PUBLISHED'" class="complete"><Check :size="14" /> 已发布</span><span v-else-if="currentStatus === 'REJECTED'" class="current">已驳回</span><span v-else-if="currentStatus === 'CHANGES_REQUIRED'" class="current">需要修改</span></div><p v-if="reviewReason" class="form-error">审核意见：{{ reviewReason }}</p><div v-if="currentStatus === 'REJECTED' || currentStatus === 'CHANGES_REQUIRED'" class="appeal-box"><label for="appeal-reason">申诉或修改说明</label><textarea id="appeal-reason" v-model="appealReason" rows="3" placeholder="说明你希望运营团队重新查看的原因" /><button class="button button-quiet" type="button" @click="appeal">提交申诉</button></div><div v-if="audits.length" class="audit-records"><h2>审核记录</h2><div v-for="audit in audits" :key="audit.id"><strong>{{ audit.action }}</strong><small>{{ audit.createdAt }}</small><p>{{ audit.reason }}</p></div></div><div class="draft-rail"><h2>我的草稿</h2><RouterLink v-for="draft in draftList" :key="draft.id" :to="`/write/${draft.id}`" :class="{ current: draft.id === draftId }">{{ draft.title || '未命名草稿' }}<small>{{ draft.status }}</small></RouterLink><p v-if="!draftList.length" class="muted">保存第一份草稿后，它会出现在这里。</p></div></aside></div>
  </div>
</template>
